void print_center(const char *msg) {
  int numspaces=(LENGTH-strlen(msg))/2;
  int i;  
  for(i=0;i<numspaces;i++)
 printf(" ");
  printf("%s\n", msg);
  return;
  
}


void title () {
 printf("\n\n");
 print_center("******");
 print_center("*****************");
 print_center(" *  ***  * ");
 printf("\n\n");
}

void readline(char *instr) {
 char c;
 int slen=0;

 c=getchar();
 while (c != '\n')
 {
  if(isalpha(c) || isspace(c))
instr[slen++]=toupper(c);
  c=getchar();
 } 
 instr[slen]='\0';
}

